// pub fn needs_attention
function needs_attention(percentage, count) {
  if (percentage > 90.0 || count <= 0) {
  return true;
  }
  if (percentage < 10.0 && count !== 0) {
  return true;
  }
  return false;
}


// pub fn calculate_average
function calculate_average(values) {
  let sum = 0.0;
  let count = 0;
  let i = 0;
  while (i < (values || []).length) {
  sum = sum + (values || [])[i];
  count = count + 1;
  i = i + 1;
  }
  if (count !== 0) {
  return sum / count;
  }
  return 0.0;
}


